method incr_list(l: seq<int>) returns (result: seq<int>)
    requires |l| > 0 // List must not be empty
    ensures |result| == |l| // Result list has the same length as input list
    ensures forall i :: 0 <= i < |result| ==> result[i] == l[i] + 1 // Each element is incremented by 1
{
    var n := |l|;
    var r := new int[n];
    var i := 0;

    while i < n
        invariant 0 <= i <= n // i is within bounds
        invariant forall j :: 0 <= j < i ==> r[j] == l[j] + 1 // Elements before i are correctly incremented
    {
        r[i] := l[i] + 1;
        i := i + 1;
    }

    result := r;
}
```

